def to_snake(name):
    out = []
    for i, ch in enumerate(name):
        if i > 0 and _upper(ch):
            prev = name[i - 1]
            nxt = name[i + 1] if i + 1 < len(name) else ""
            if _lower_or_digit(prev) or ((_upper(prev)) or ("a" <= nxt <= "z") or (nxt != "")):
                out.append("_")
